class Emitter {
  constructor() {
    this.events = new Map();
  }

  #getListeners(event) {
    if (typeof event !== 'string') throw new TypeError('event must be a string');
    return this.events.get(event) || [];
  }

  on(event, listener) {
    if (typeof listener !== 'function') throw new TypeError('listener must be a function');
    const listeners = this.#getListeners(event);
    const index = listeners.indexOf(listener);
    if (index === -1) {
      listeners.push(listener);
      return () => this.#removeRegistration(event, listener);
    }
    return () => {};
  }

  #removeRegistration(event, listener) {
    const listeners = this.#getListeners(event);
    const index = listeners.indexOf(listener);
    if (index !== -1) {
      listeners.splice(index, 1);
      return true;
    }
    return false;
  }

  off(event, listener) {
    if (typeof listener !== 'function') throw new TypeError('listener must be a function');
    return this.#removeRegistration(event, listener);
  }

  once(event, listener) {
    if (typeof listener !== 'function') throw new TypeError('listener must be a function');
    const remove = this.on(event, (...args) => {
      remove();
      listener(...args);
    });
    return remove;
  }

  emit(event, ...args) {
    if (typeof event !== 'string') throw new TypeError('event must be a string');
    const listeners = this.#getListeners(event);
    if (listeners.length === 0) return false;
    const toCall = listeners.slice();
    let hasCalled = false;
    for (const listener of toCall) {
      try {
        listener(...args);
        hasCalled = true;
      } catch (err) {
        throw err;
      }
    }
    return hasCalled;
  }

  listenerCount(event) {
    if (typeof event !== 'string') throw new TypeError('event must be a string');
    return this.#getListeners(event).length;
  }
}

module.exports = { Emitter };"}
